end

function ActivityCrisisContractQuestNodeCell:Awake()
end

function ActivityCrisisContractQuestNodeCell:RefreshShow(data,state)
    self.data = data
    local questVo = ActivityCrisisUtils.GetCrisisEventLevelVo(self.data.questId)

    local isUnLock = self:CheckIsUnLock()
    KTool.SetActive(self.ImgBgLock.gameObject,not isUnLock)
    KTool.SetActive(self.ImgBg.gameObject,isUnLock)
    if isUnLock then
        CfUtils.FillText(self.TxtTitle,questVo.name)
        KTool.SetActive(self.ImgNew.gameObject,self.data.new == 1)
        local isGet = self.data.receivedTaskNum == self.data.taskNum
        KTool.SetActive(self.ImgGet.gameObject,isGet)
        local state = isGet and 2 or 1
        CfUtils.SetUISwitchText(self.TxtDeco2,state)
    else
        KTool.SetActive(self.ImgNew.gameObject,false)
        KTool.SetActive(self.ImgGet.gameObject,false)
        local time = self.data.unlockCountdown - os.time()
        CfUtils.FillText(self.LockTitle,questVo.name)
        CfUtils.FillText(self.TxtCutTime,localize("_num_后开启",{_num_ = CfUtils.GetTimeHMS11(time) }))
    end
end

function ActivityCrisisContractQuestNodeCell:CheckIsUnLock()
    if checkNumber(self.data.unlockCountdown) > 0 and checkNumber(self.data.unlockCountdown) - os.time() > 0 then
        return false
    end
    return true
end

function ActivityCrisisContractQuestNodeCell:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
end

return ActivityCrisisContractQuestNodeCell